from pathlib import Path
import json,hashlib,zipfile,shutil,sys
R=Path(__file__).resolve().parents[1];slug=sys.argv[1];P=R/slug
j=lambda p:json.loads(p.read_text());jw=lambda p,v:p.write_text(json.dumps(v,indent=2)+'\n');layout=j(P/'source/layout.json');title=layout['title'];seatcount={'willow-quay-tea-garden':12,'lantern-souk-bazaar':2,'resonance-media-house':9,'celestial-transit-garden':0}[slug]
used={'greg-reference.png','lounge-chair-north.png','low-lounge-table.png'}
master={'willow-quay-tea-garden':'tea-garden-clear-landing-master.png','lantern-souk-bazaar':'bazaar-environment-safe-ring-master.png','resonance-media-house':'media-environment-clean-seats-master.png','celestial-transit-garden':'portal-environment-garden-boundaries-master.png'}[slug];used.add(master)
brief={'willow-quay-tea-garden':'tea','lantern-souk-bazaar':'bazaar','resonance-media-house':'media','celestial-transit-garden':'portal'}[slug]
if (R/'source'/(brief+'-generation-prompt.txt')).exists():used.add(brief+'-generation-prompt.txt')
used.add('generation-history.json')
if slug=='resonance-media-house':used.update(['industrial-chair40-native.png','congress-low-table.png','industrial-chair-generated-master.png','contemporary-furniture-provenance.json'])
for n in used:shutil.copy2(R/'source'/n,P/'source'/n)
shutil.copytree(R/'tools',P/'portable-tools',dirs_exist_ok=True,ignore=shutil.ignore_patterns('__pycache__'))
(P/'README.md').write_text(f'''# {title}\n\n{layout['category']} — {layout['style']}. An additive original native32 map template; all earlier maps preserved.\n\n## Delivered\n- Actual orthogonal TMJ, relative PNG atlases and companion WAM in map32/.\n- Native occupied/empty/collision previews decoded from the compiled atlas. Greg is a 32px source-authored preview fixture only.\n- Original generated environment master, deterministic composition/compiler source, collision/anchor/area contract and reproducible native movement fixture.\n\n## Layout counts\n{seatcount} visible seats; {len(layout['anchors'])} authored test anchors including the spawn. Counts describe artwork and routes, not supported-user capacity. Willow's gazebo uses two standing conversation anchors rather than chairs. Portal arches are decorative, inactive destination placeholders.\n\n## Status\nStatic collision, anchor and atlas tests plus pinned native movement replay are supplied in validation/. No live room/browser/keyboard/device/network/multi-user/service test is claimed. No publication, engine edit or merge. Water, foliage and lights are STATIC artwork; no animation is claimed.\n\n## Honest feature scope\nArtwork and editor-ready areas only. No AI generation, recording, music service, ecommerce checkout, seller bot or teleport target is operational. Configure appropriate integrations and permissions separately in a new room. Blank portal destinations stay disabled. Decorative counters are fixed background art; public approach anchors are tested, staff access behind counters is not offered.\n\n## Setup\nServe map32/ together and select {slug}.tmj as the custom TMJ. The adjacent WAM is a portable setup candidate: Custom TMJ does NOT automatically import it. Back up any existing room WAM before changes; create a separate test room. See integration/ROOM-SETUP.md.\n\n## Rebuild\nVisual boundary sheets are regenerated with python tools/check_spawn_and_boundaries.py {slug}. The source-replay ZIP has tools/, source/ and {slug}/ at its root. With Python3, Pillow and NumPy: python tools/build_maps.py --map {slug}. Then: node tools/native/route-audit.cjs {slug}. No repository, paid API, remote asset download or engine change is needed. Source-extracted engine methods and EasyStar0.4.4 are bundled with source pin metadata.\n''')
(P/'PROVENANCE.md').write_text('''# Provenance\n\nThe environment is original project artwork generated with the built-in image generation tool from a task-specific prompt. Master pixels are bundled. No reference artwork was copied and no third-party CC0/public-domain claim is made. Social maps use the project-authored accepted lounge chair and low-table family from the prior flagship source kit, at native proportions without stretching. Media House instead uses newly generated charcoal task chairs at40×45 and contemporary oak tables at80×46, with bundled provenance and native placement records.\n\nGreg Gulf-outfit v3 is a project-authored review fixture, SHA256 e88ba016c58f6bc7616c831c3c56a4656e66772794940af93c0c0835e85a987d; not an upstream WorkAdventure sprite. It is excluded from runtime. Fixture attribution: https://github.com/BAWES-Universe/universe-ai-creator-kit/blob/67382dc97f494c230e93f0cf67e478df6e5b6d17/docs/catalogue/wokas.md#reference-greg32-map-fixture\n\nPrior furniture lineage: https://github.com/BAWES-Universe/universe-maps/blob/03d83f2/map-mocks/expanded-office-02/source/frozen-review-package/art-meeting/source/generation-record.json\n\nThe source fixture includes unchanged engine methods pinned to 60e7afdc3f96ef32525597cd46bd41175d61a2ef and EasyStar0.4.4, with source manifest; this is a validation fixture rather than an engine modification.\n''')
(P/'integration/ROOM-SETUP.md').write_text('''# Safe setup\n\n1. Create a new review room; do not replace an existing production room. Serve the complete map32 closure at one origin with relative PNG paths preserved.\n2. Choose the TMJ as Custom TMJ. This produces a room-specific WAM and does not import the companion WAM automatically. Keep the real room mapUrl and any existing areas unless deliberately migrating them with backup.\n3. The Tiled start rectangle is32×32, with native margin16 selecting its center. The WAM receiver is8×8 and remains fully inside that same silent tile (WAM has no native margin). Only the center tile is silent. No broad social silence, scripts, focus zones, proximity-radius overrides or runtime visibility changes are installed.\n4. Companion WAM areas without properties are named editor placeholders, not activated capabilities. Add and test native meeting/media/website/portal properties through supported room editing after choosing destinations and services. Do not enter fake URLs or credentials.\n5. Portal links, bots, ecommerce, Imagine and ImagineMusic need real configuration and relevant user permission. This package does not provision or imply those services.\n6. Test the arrival, every doorway/bridge in both directions, every seat approach/exit, mobile touch, viewport changes and multi-user communication in the actual deployment before production use.\n7. Keep the original source/manifest. Publication and live URL verification remain separate release steps.\n''')
files=[dict(path=str(p.relative_to(P)),bytes=p.stat().st_size,sha256=hashlib.sha256(p.read_bytes()).hexdigest()) for p in sorted((P/'map32').iterdir()) if p.is_file()]
report=dict(title=title,slug=slug,category=layout['category'],style=layout['style'],nativeTileSize=32,world=layout['world'],visualSeats=seatcount,anchorCount=len(layout['anchors']),runtime=files,geometry=j(P/'validation/geometry.json'),nativeRoutes={k:v for k,v in j(P/'validation/native-routes.json').items() if k!='rows'},revision='r03-systematic-fixture-pass',status=dict(independentReview='pending',compiled=True,staticValidated=True,nativeRouteReplay=True,livePlaytest=False,published=False,animated=False,externalServicesConfigured=False),preview='review/occupied-native.png',runtimeZip=slug+'-runtime.zip',sourceZip=slug+'-source-replay.zip')
jw(P/'MANIFEST.json',report)
with zipfile.ZipFile(P/(slug+'-runtime.zip'),'w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted((P/'map32').iterdir()):z.write(p,p.name)
with zipfile.ZipFile(P/(slug+'-source-replay.zip'),'w',zipfile.ZIP_DEFLATED) as z:
 for p in sorted((R/'tools').rglob('*')):
  if p.is_file() and '__pycache__' not in p.parts:z.write(p,'tools/'+str(p.relative_to(R/'tools')))
 for n in used:z.write(R/'source'/n,'source/'+n)
 for p in sorted(P.rglob('*')):
  if not p.is_file() or p.suffix=='.zip' or 'portable-tools' in p.parts or p.name=='FREEZE.json':continue
  if p.parent==P/'source' and p.name.endswith('-master.png') and p.name not in used:continue
  if p.name.startswith('boundary-sweep-') and p.suffix=='.png':continue
  z.write(p,slug+'/'+str(p.relative_to(P)))
jw(P/'FREEZE.json',dict(slug=slug,manifestSHA256=hashlib.sha256((P/'MANIFEST.json').read_bytes()).hexdigest(),runtimeZipSHA256=hashlib.sha256((P/(slug+'-runtime.zip')).read_bytes()).hexdigest(),sourceZipSHA256=hashlib.sha256((P/(slug+'-source-replay.zip')).read_bytes()).hexdigest(),immutableUntilExplicitRevision=True))
print(P/'MANIFEST.json')
